insert into public.publications(id,title,kind,summary,html,topics,schools,author_name,published_at,status,source_url) values('20000000-0000-4000-8000-000000000001','Psicologia Junguiana','base_text','Texto-base do acervo original.','<p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; height: 12pt; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; height: 12pt; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: center;"><span style="color: rgb(0, 0, 0);">INTRODUÇÃO AO MÉTODO TIPOLÓGICO DE C. G. JUNG</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; height: 12pt; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; height: 12pt; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: center;"><span style="margin-right: 0px; margin-left: 0px; width: 20.03px; height: 20px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/jung/image1.png" style="width: 20.03px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; height: 12pt; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; height: 12pt; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: right;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">POR HORUS C.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">O fundamento que move esta atual análise é um dos métodos mais empíricos e funcionais da psicologia complexa, </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“o método tipológico”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">.</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt1" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[1]</a></sup><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Para tanto, torna-se fundamental a abordagem dos pontos basilares desta tipologia psicológica para que seja possível a progressão deste estudo. A princípio, o conceito que sedia toda e qualquer discussão a este respeito são as “</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">atitudes psicológicas”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. Na obra inaugural de sua psicologia, </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Tipos Psicológicos</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">,</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt2" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[2]</a></sup><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Jung define </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“atitude”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;(</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Einstellung</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) como </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“a disposição da psique de agir ou reagir em certa direção”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">.</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt3" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[3]</a></sup><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Empregando a noção de frequência, </span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">i.e.</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, participação cada vez mais direta de um ou outro tipo de atitude na consciência, perceptíveis ao Eu, torna-se possível abstrair a noção basilar de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“atitudes habituais”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">.</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt4" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[4]</a></sup><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Em seus escritos, a Srta. Toni Wolff sumariza esta ideia como aquela que </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“determina a totalidade de todos os conteúdos (conscientes) num viés psicológico”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, à qual </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“não é idêntica a outras categorias, como por exemplo, </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">caracterológicas</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">&nbsp;ou morais, ou com classificações condizentes com tipos ocupacionais ou de aptidão”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">.</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt5" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[5]</a></sup><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Em seus textos, além deste basilar termo, o Dr. C. G. Jung também os denominou de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“tipos de atitude gerais”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">, devido a seu caráter genérico.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">O conceito de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“atitude”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;puro e isolado é inexistente na prática, visto que a par de sua noção abstrata, há também conceitos que se interrelacionam com ele, a saber, </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">compensação</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;e </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">constelação</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. O primeiro diz muito acerca da atitude habitual, pois aborda o fato que, para toda atitude consciente, um contrapeso atitudinal, ou como queira o chamar, é realizado no inconsciente, de forma que haja uma </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">tendência psicológica comum ao equilíbrio</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;(o que pode ser comparado a noção de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“entropia” </span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">na física</span><span style="color: rgb(0, 0, 0);">)</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. Já o último termo, ressalta outro aspecto da </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“atitude”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;ao qual Jung chama a atenção, </span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">i.e.,</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;o ato de ter determinada atitude. Para o autor, isso se dá quando se está </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“pronto para algo determinado, mesmo que esse ‘algo’ seja inconsciente, já que possuir uma atitude é análogo a uma direção apriorística a algo determinado, seja este presente na consciência ou não”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">.</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt6" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[6]</a></sup><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Paralelamente, em </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">A Dinâmica do Inconsciente</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">,</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt7" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[7]</a></sup><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Jung define que uma </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“constelação”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;é expressa quando </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“uma situação externa provoca um processo psicológico, consistindo em uma coleta ou fornecimento de certos </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">conteúdos</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">. A expressão ‘estar constelado’ diz que alguém adotou </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">uma ‘atitude</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">’ de</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">&nbsp;expectativa preventiva, a partir da qual irá reagir de forma muito específica”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">.</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt8" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[8]</a></sup><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Decerto, poder-se-ia tentar formular um processo linear, do qual o movimento de constelação desencadeia uma atitude que, por sua vez, é compensada pelo inconsciente. Contudo, tal processo se submete totalmente à </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">exigência prática</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">, podendo ser facilmente alterado em escopo para que sirva aos fatos. Neste sentido, resta de clareza apenas a íntima relação que cada movimento apresenta entre si, mas nunca sua ordem ou linearidade explicita.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Diante dessas noções, eleva-se ao método tipológico seu objeto de estudo, os </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“tipos de atitudes habituais”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. Para Jung, seu conceito de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“tipos”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;(</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">typus</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) deve, igualmente, ser considerado neste plano. Em seu sentido amplo, tal termo refere-se a </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“um exemplar ou padrão que, caracteristicamente, reflete a natureza de uma espécie ou generalidade”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, i.e, trata-se </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">de um modelo geral de atitude</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">.</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt9" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[9]</a></sup><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Já em sentido estrito, conforme o método prescreve, separa-se os tipos habituais em duas outras classes, uma destinada à </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“atitude geral”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;e outra referente a </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“atitudes funcionais”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. A partir da primeira, abstrai-se um par de atitudes mutuamente complementares e opostas, seguindo a noção de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">compensação</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, as quais Jung nomeou de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“extroversão”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;e </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“introversão”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">, sendo elas mecanismos das quais o sujeito age ou reage em relação ao objeto.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">O emprego do mecanismo de ação e reação subjetiva em relação ao objeto não partem de mera abstração intelectual de Jung, mas sim destacam a participação efetiva de um </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“processo de adaptação momentâneo”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, traço pela qual a consciência é caracterizada. Ambos os princípios atuam como</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">&nbsp;“extremos” </span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">habituais, pelos quais o centro é mediado pelo </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Eu consciente”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. Neste sentido, conforme elucida a Srta. Wolff, a noção de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">objeto”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">atua como </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“termo coletivo para um (ou mais) conteúdos do ambiente empírico ou mental, além do mundo externo”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">.</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt10" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[10]</a></sup><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Enquanto, a noção de sujeito, </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“refere-se ao indivíduo psicológico, incluindo seu mundo interior psicologicamente objetivo”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">.</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt11" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[11]</a></sup><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Nessa ótica, no entanto, é fulcral destacar que por </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“sujeito”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, assume-se um princípio distinto de </span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Eu consciente</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, na medida em que este último é </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“condutor e portador, em parte voluntário e em parte involuntário, das atitudes e de seu direcionamento específico”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">.</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt12" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[12]</a></sup></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">O </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“conteúdo”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;que flui entre essas extremidades, incluindo o centro com o </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Eu consciente</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, é denominado por Jung como </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“energia psíquica”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, </span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">i.e.,</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;uma abstração dos movimentos dinâmicos entre conteúdos e estruturas psicológicas.</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt13" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[13]</a></sup><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Sendo um aspecto quantitativo, a </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“libido”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;— como também fora chamada — apresenta vínculo com a atenção, interesse e valorização consciente e inconsciente. Dessa forma, torna-se possível, energeticamente, distinguir uma atitude extrovertida de uma introvertida. Enquanto na primeira o </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“fluxo energético”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;parte em direção ao objeto, de forma que, simbolicamente, ele atribui sua alma à realidade objetiva </span><span style="color: rgb(0, 0, 0);">(</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">que está no domínio do objeto</span><span style="color: rgb(0, 0, 0);">)</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">; na última, o fluxo energético é recolhido para si, retornando ao sujeito e sua psicologia individual, de forma que, simbolicamente, o objeto soa vivo e influente o suficiente para feri-lo, precisando se defender abstratamente do contato direto com este. </span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Segundo </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">o princípio da compensação</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, seja qual tipo de atitude geral desempenhe o habitual da consciência de um sujeito, seu inconsciente atua de forma complementar, assumindo a atitude oposta. Neste sentido, um extrovertido possui um inconsciente introvertido, enquanto um introvertido possui um inconsciente extrovertido. Tal relação entre consciência e inconsciência proporciona um </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“equilíbrio psicológico”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, na medida em que também torna impossível a existência de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“tipos plenamente puros”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, pois por mais frequente que a atitude extrovertida seja para um determinado indivíduo, jamais abrange a totalidade de seu sistema psicológico. Ainda na introdução de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Tipos</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, Jung enfatiza tal fato ao declarar que </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“através da compensação, emergem </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">caráteres</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">&nbsp;secundários, ou ‘tipos’, que apresentam uma imagem que é extraordinariamente difícil de decifrar, tão difícil que, decerto, há certa inclinação a negar a existência dos tipos em geral e em crer apenas nas diferenças individuais”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">.</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt14" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[14]</a></sup><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">A figuração excessiva diante desses aspectos </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“negados”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;é um traço de pura empiria, pois seu retrato se encontra vivo na contínua relação que a humanidade, incluindo o homem moderno, possui com o inconsciente. É certo que, grande parte desta atitude provém de um sacrifício individual pelo qual aspectos da própria alma </span><span style="color: rgb(0, 0, 0);">(</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">ou psique</span><span style="color: rgb(0, 0, 0);">)</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;são alinhados na relação, majoritariamente, com o objeto. Essa espécie de</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">&nbsp;“relacionamento sujeito-objeto”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;remonta ao fato de que </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“quanto mais longe retorna-se a história, mais torna-se possível ver a personalidade (individual) desaparecendo no embrulho do coletivo”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">.</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt15" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[15]</a></sup><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;O combustível para isso, no entanto, tem sido elucidado pela mente moderna como </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“mecanismo de projeção” </span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">e, de forma semelhante, empregada para ressaltar determinada</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">&nbsp;“participação mística” </span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">que residiu e reside em relação ao objeto.</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt16" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[16]</a></sup><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Em suma, destinou-se ao objeto grande massa de peso subjetivo, de forma que, no remontar da história da humanidade, </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">percebe-se elevada quantidade de conteúdos e fatos psicológicos atrelados a forças externas</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, pertencentes a um </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“não-Eu”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;e, portanto, negligenciadas.</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt17" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[17]</a></sup><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Um exemplo prático são os </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">daimonion</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;gregos, cuja atividade era tanto a oferta de ajuda quanto a má sugestão. Neste sentido, para um extrovertido, sua introversão poderia desempenhar um papel alheio, como um daimon, e perturbar a consciência que, em sua ótica, pode o ver como algo não pertencente a si mesmo.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Outro aspecto de igual impacto para esse </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“relacionamento sujeito-objeto”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;são as </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“transformações subjetivas”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. Em sua obra </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Arquétipos e o Inconsciente Coletivo</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">,</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt18" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[18]</a></sup><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Jung explora alguns fenômenos que se relacionam com a </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“alteração da consciência”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, que demonstram certa frequência na vivência psicoterapêutica. Entre eles se destacam a noção de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“diminuição da personalidade”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“inflação da personalidade”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;e </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“possessão da personalidade”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. A primeira refere-se ao fenômeno primitivo da </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“perda de alma”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, visto na </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“quebra de expectativa”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;quando uma atitude falha na consciência; a segunda aborda a crença de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“possuir o aspecto alheio para si”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, de forma que haja uma falsa crença de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“sucesso”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, é o caso que Jung aborda com a </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“crença da inexistência do não-Eu”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. A última refere-se a uma inversão da anterior, aborda a possessão subjetiva pelas qualidades do </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">não-Eu</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, expressa na obsessão senão na supervalorização e exagero deste. Todos esses fenômenos são grande parte das atitudes que um extrovertido possui em relação a sua introversão e, por meio da projeção, a alguém mais introvertido que este </span><span style="color: rgb(0, 0, 0);">(</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">o mesmo deve ocorrer com um introvertido em relação a sua extroversão</span><span style="color: rgb(0, 0, 0);">)</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">A par dos tipos de atitudes gerais, também cabe a análise basilar dos </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“tipos de atitudes funcionais”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, ou apenas </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“tipos funcionais”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">.</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt19" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[19]</a></sup><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;No método tipológico, esse termo é dado a respectivas funções que desempenham um determinado papel psicológico na adaptação subjetiva. De forma similar, também abrangem uma </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“hierarquia energética”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, formulada sob a ótica da </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">frequência</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;e </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">compensação</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;mútua entre si. Por serem, em parte, </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">funções</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, deixam de apresentar um mero </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“modo de agir e reagir frequente”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;para tornarem-se </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“ações e reações mentais que perpetuam fundamentalmente as mesmas sob diferentes circunstâncias”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">.</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt20" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[20]</a></sup><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Além disso, estas carregam em si certa exclusividade — no campo do direito, seria similar a registros </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“sui generis”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;— de forma que, por mais tentador que venha a ser resumir um processo funcional por outro, tal tentativa nunca será totalmente eficaz no que se propõe.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Na psicologia complexa, compreende-se a existência de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">quatro tipos funcionais</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, aos quais se separam, arbitrariamente, dois outros grupos: os</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">&nbsp;tipos racionais</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;e os </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">tipos irracionais</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. O primeiro grupo abrange tipos coordenados e </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">orientados pela “razão”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;e suas respectivas leis, i.e., usam de critérios, valores e comparações dedutivas para estabelecer sua adaptação ao meio, a essa classe pertencem os tipos </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">pensamento</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;e </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">sentimento</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. Por outro lado, o último grupo se denomina </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">irracional </span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">na medida em que não são anti racionais, mas sim que</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">&nbsp;transcendem as leis de razão</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;e procuram uma relação com o conteúdo dado, ao invés de processá-los, a este grupo pertencem os tipos </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">sensação</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;e </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">intuição</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. Cada uma dessas categorias funcionais respeitam o </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">princípio da compensação</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">, logo, o tipo pensamento e sentimento se complementam e se opõem mutuamente, da mesma forma como ocorre com o tipo sensação em relação ao tipo intuição. </span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">A descrição de cada natureza funcional exige um plano melhor esboçado. Para a atual discussão, no entanto, a simplificação utilizada por Jung em </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">A Dinâmica do Inconsciente</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;basta para suprir a atual necessidade. Neste escrito, o autor denomina de</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">&nbsp;“sensação”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;como a função que </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“comprova que algo existe”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, na medida em que realiza uma tradução da realidade sensorial para linguagem psíquica, i.e., as imagens; por </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“pensamento”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, a função responsável pela </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“interpretação do percebido”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, através de uma avaliação descritiva e fria dos conteúdos; por </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“sentimento”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, a função responsável pela “</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">estimação do valor subjetivo que determinada coisa possui para o Eu”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, atribuindo-a um valor subjetivo; </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">e a intuição diz sobre o que está implícito para a consciência</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">, sendo uma tradução da realidade interior e arquetípica em imagens para a consciência. Quando um desses determinados tipos é mais frequentemente empregado no processo de adaptação do Eu com seu meio, fala-se de um tipo sensação, tipo pensamento, tipo sentimento ou tipo intuição.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">A </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“hierarquia energética”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;que existe entre esses tipos funcionais é dada em parte pelo </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“processo de adaptação”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;e em parte pela </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“pressão externa ou interna”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;— ou necessidade — manifesta em determinado indivíduo. Dessa forma, cada tipo é dotado de determinado peso psicológico — expresso pelo interesse ou energia — de forma que estruturam diversas posições funcionais distintas entre si. Além disso, a relação de oposição complementar entre os pares de tipos exercem grande influência nesse processo estrutural, pois caso um entre os dois tipos funcionais presentes nesta relação seja </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“privilegiado energeticamente”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, seu par é delegado a uma categoria gradativamente inferior ou de menor tensão energética. Dessa forma, ocorre uma oposição também entre os níveis estruturais tipológicos, na medida em que sempre há uma </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“tensão”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;e </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">contratensão</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;manifesta entre as funções ali dispostas.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Entre as posições funcionais, sempre há um par de tipos que exerce maior influência na adaptação individual, visto a diferença de valor energético entre a faculdade preferida e a </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“desprezada”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. Em </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Tipos</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, Jung associa a este par o título </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“função superior”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;(“</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Hauptfunktion</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) ao tipo com maior energia e </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“função inferior”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;(</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Minderwertige Funktion”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) para seu oposto complementar e, consequentemente, de menor energia consciente — o que implica sua atividade fora da vontade consciente. Nas descrições originais do texto, no entanto, o emprego de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“função superior”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;e </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“função inferior”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;seria, de certo modo, incorreto; tal transcrição ainda sim é funcional, por mais que Jung gostaria de abordar sobre uma </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“função de maior tensão”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;e </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“função de menor tensão”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, respectivamente, senão com grau de diferenciação — i.e., conscientização funcional — elevado e limítrofe. O outro par funcional, que devido a não oposição complementar com o preferido, é delegado a uma posição neutra ou relativamente consciente. Jung designa a eles o termo </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“funções auxiliares”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;(“</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Hilfsfunktion</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">), que pode ser traduzido numa visão energética como </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“funções de tensão relativa”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, senão </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“funções de tensão moderada”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">O desenvolvimento tipológico, juntamente com a adaptação individual, se dá pela dinâmica energética psicológica. Embasando-se nas teses do século XX, especialmente entre as do psicólogo William James e psiquiatra Pierre Janet, Jung formulou sua própria, e fundamental, perspectiva da consciência, como órgão de efêmera duração, destinada à adaptação individual ao ambiente. Para tanto, as noções de Janet entre os três traços notórios da consciência — </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">direção</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">, concentração e intensidade</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;— são preservadas e adaptadas à finalidade clínica da psicologia, com uma breve mescla dos fatores para a composição da noção primal da consciência, como órgão </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“unilateral”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. Dessa noção, Jung conseguiu explicar algumas falhas metodológicas e</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">&nbsp;“dogmatismos sérios”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;no campo da filosofia e psicologia antigas e modernas como produtos da </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“unilateralidade dos pontos de vista individuais”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, conforme James já havia </span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">o feito</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;em seu mais popular escrito, </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Pragmatism</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">A extensa discussão formalizada no primeiro capítulo de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Tipos</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;— incluindo a breve introdução — convida o leitor a reflexão crítica sobre concepções universais e o vício unilateral, além de introduzir a reconsideração teórica no que tanto James quanto Jung </span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">chamavam</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“equação pessoal”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. Nesse sentido, a soma ou síntese das faculdades e atitudes da consciência individual — como órgão de adaptação unilateral — constituíram uma forma genérica pela qual um sujeito percebia a realidade e, ainda mais, a compreenderia em essência. A partir disso emerge a noção de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“tipo psicológico”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, como associação energética entre a atitude geral e função superior de um determinado indivíduo, sendo essa combinação o fruto da interação que o Eu realiza com o externo, o ambiente e a sociedade — por isso, pode vir a ser manifesta em obras e produções materiais e intelectuais. As demais faculdades funcionais, contudo, não são esquecidas nem meramente ignoradas, elas permeiam a atitude habitual de forma inconsciente, como um </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“não-Eu”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;psicológico. Grande parte do desenvolvimento dessas funções se dá pelos </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“resquícios de déficits resultantes da adaptação psicológica, os quais se acumulam no decorrer da vida; através desta deficiência um desarranjo da adaptação se desenvolve, forçando o sujeito em direção a compensação”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Um determinado </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“tipo psicológico”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;refere-se a síntese entre a função superior e uma atitude habitual e, em seguida, a identificação individual com esse produto. Fala-se não mais de um tipo pensamento ou tipo extrovertido, mas de um </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“tipo pensamento extrovertido”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, em que a </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">função superior</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;é o pensamento e a atitude habitual, a extroversão. Consequentemente, a </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">função inferior</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;deste tipo, o par oposto do pensamento, o sentimento, se une com a atitude oposta à consciência, a introversão, e produz um </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“tipo sentimento introvertido”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;inferior e inconsciente. Sendo inconscientes, apresentam </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">caráter atemporal, síncrono, infantil, arcaico e inadaptado</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, cuja tendência maior é </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">a compensação dos exageros e atitudes da consciência</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">. Logo, por mais sentimental e introvertido que seja o inconsciente deste caso, pouco dele vai se preservar em um tipo sentimental introvertido consciente, que opera sua adaptação ao meio com esse tipo psicológico.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Este mesmo tipo pensamento extrovertido, além de seu sentimento introvertido inferior, possui também a possibilidade de desenvolver funções auxiliares, a sensação e a intuição. </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Por via de regra, todo material e conteúdo na consciência opera com a atitude habitual da mesma</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, logo, se a sensação e a intuição vierem a serem diferenciadas, elas também, no nosso caso, seriam extrovertidas, da mesma forma que se permanecerem inconscientes, continuaram sendo introvertidas. Naturalmente, as funções auxiliares servem de apoio, menos desenvolvido, para a adaptação, especialmente quando a função superior falha em suas atitudes. O processo de diferenciação pode ser visualizado nas </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“personas”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;conscientes, visto serem produtos da </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“identificação do Eu com as funções superiores”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">.</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt21" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[21]</a></sup><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Estas </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“personas”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;tem a finalidade de garantir a adaptação e proteção individual (uma espécie de seleção natural de atitudes) e são comumente expressas, como declara a Srta. Wolff, </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“uma espécie de máscara ou papel que corresponde às normas coletivamente válidas em seu respectivo espírito-da-época”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">.</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt22" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[22]</a></sup></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">A identificação entre um determinado tipo e o Eu consciente é, a princípio, dada </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">inconsciente</span><span style="font-style: italic; color: rgb(0, 0, 0);">mente</span><span style="color: rgb(0, 0, 0);">: não se sabe quando se ajusta ao fundamento de uma função, e o pensamento que emerge quando se confronta uma identificação sempre é uma dúvida, uma incerteza e um desconhecimento.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Devido a finalidades didáticas, na elaboração dos </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Tipos</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, Jung apresenta a síntese de oito tipos psicológicos, contudo, meramente ideais. Esses </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“tipos puros”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, como são chamados pelo autor, são apenas abstrações gerais da individualidade observada na clínica e nada nos dizem sobre a realidade dos objetos narrados. A individualidade, portanto, subjuga a aplicabilidade da idealização de tipos puros e, por isso, é inegável que no trabalho tipológico, é dever do médico tolerar o geral e o individual com iguais pesos, sem supervalorizar um em detrimento do outro.</span></p><hr style="width: 33%; height: 1px; color: rgb(128, 128, 128);"><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref1" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[1]</a><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Quem cunhou este termo foi o Dr. Heraclito Pinheiro em seus escritos, em destaque, </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“O método de Jung”</span><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. O termo pode ser ainda mais valorizado se considerar os escritos da Srta. Toni Wolff em seu livro introdutório sobre a psicologia complexa, de nome </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Studien zu C. G. </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Jung''s</span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">&nbsp;Psychologie”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref2" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[2]</a><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;</span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Tipos Psicológicos”</span><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;foi inicialmente publicado em 1921 sob o título alemão </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Psychologische Typen”</span><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">; a tradução usada no decorrer deste texto se refere a edição em inglês, revisada pelo Dr. C. G. Jung, de nome </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Psychological Types or, The Psychology of Individuation”</span><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, publicada em 1923. A partir deste ponto, ele será referido com o termo </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Tipos”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref3" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[3]</a><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;JUNG, Carl Gustav. </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Psychological Types or, The Psychology of Individuation”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">. 1. ed. Inglaterra: Pantheon Books, 1923. 526 p. </span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref4" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[4]</a><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;Este termo não é destacado nos escritos clássicos da psicologia complexa, mas é comumente empregado para se referir a atitudes de maior frequência consciente.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref5" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[5]</a><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;WOLFF, Toni Anna. </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Studien zu C. G. </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Jung’s</span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">&nbsp;Psychologie”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">. 3. ed. Suíça: Daimon Verlag, 2008. 82 p.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref6" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[6]</a><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;JUNG, Carl Gustav. </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Psychological Types or, The Psychology of Individuation”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">. 1. ed. Inglaterra: Pantheon Books, 1923. 526 p</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref7" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[7]</a><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Para melhor precisão dos conteúdos apresentados, </span><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">fora</span><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;escolhido a tradução da obra </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Die Dynamik des Unbewussten”</span><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;em espanhol, de nome </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“La Dinámica de lo Inconsciente”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">, por Trotta Editorial.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref8" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[8]</a><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;JUNG, Carl Gustav. </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“La Dinámica de lo Inconsciente”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">. Espanha: Trotta Editorial, 2011. 99 p.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref9" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[9]</a><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;JUNG, Carl Gustav. </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Psychological Types or, The Psychology of Individuation”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">. 1. ed. Inglaterra: Pantheon Books, 1923. 612 p</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref10" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[10]</a><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;WOLFF, Toni Anna. </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Studien zu C. G. </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Jung’s</span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">&nbsp;Psychologie”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">. 3. ed. Suíça: Daimon Verlag, 2008. 85 p.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref11" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[11]</a><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;Ibid.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref12" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[12]</a><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;Ibid.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref13" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[13]</a><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Jung chama atenção e explica sobre o dilema da </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“energética psicológica”</span><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;no primeiro capítulo de sua obra </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“A Dinâmica do Inconsciente”</span><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;</span><span style="font-size: 10pt; color: rgb(0, 0, 0);">(</span><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">CW 8</span><span style="font-size: 10pt; color: rgb(0, 0, 0);">)</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">. A leitura deste texto, assim como os capítulos subsequentes, é essencial para um retrato mais fidedigno da tipologia psicológica formulada pelo autor.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref14" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[14]</a><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;JUNG, Carl Gustav. </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Psychological Types or, The Psychology of Individuation”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">. 1. ed. Inglaterra: Pantheon Books, 1923. 10 p</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref15" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[15]</a><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;Ibid. 18 p</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref16" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[16]</a><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Diferentemente de Freud, Jung tem outra concepção de</span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">&nbsp;“projeção”</span><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, a qual muito se relaciona com a noção de </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“participation mystique”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;do sociólogo francês Lucien Lévy-Braul.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref17" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[17]</a><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;O termo </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“não-Eu”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;é extremamente cabível e remonta as contribuições da analista Esther Harding para o campo da psicologia complexa.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref18" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[18]</a><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp; Para melhor precisão dos conteúdos apresentados, </span><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">fora</span><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;escolhido a tradução da obra </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Die Archetypen und das Kollektive Unbewußte”</span><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;em espanhol, de nome </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Los Arquetipos y lo Inconsciente Colectivo”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">, por Trotta Editorial.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref19" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[19]</a><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;O fato que resultou na confecção dos tipos funcionais foi uma série de correspondências realizadas entre o Dr. C. G. Jung com seu colega e amigo Hans Schmid-Guizan; tal documento pode ser lido na obra </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“The Question of Psychological Types”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref20" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[20]</a><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;JUNG, Carl Gustav. </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Psychological Types or, The Psychology of Individuation”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">. 1. ed. Inglaterra: Pantheon Books, 1923. 547 p </span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref21" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[21]</a><span style="font-size: 10pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;WOLFF, Toni Anna. </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Studien zu C. G. </span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Jung’s</span><span style="font-size: 10pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">&nbsp;Psychologie”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">. 3. ed. Suíça: Daimon Verlag, 2008. 84 p.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 12pt; font-family: &quot;Newsreader&quot;; text-align: justify;"><a href="#ftnt_ref22" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[22]</a><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;Ibid.</span></p>',array['jung']::text[],array[]::text[],'',null,'published','https://docs.google.com/document/d/1b6u9iQifam8Cg-P06fI04IfY2pny81FM6qg_lcWTDYc/edit') on conflict(id) do nothing;
insert into public.publications(id,title,kind,summary,html,topics,schools,author_name,published_at,status,source_url) values('20000000-0000-4000-8000-000000000002','Socionics','base_text','Texto-base do acervo original.','<p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; height: 11pt; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; height: 11pt; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal"></span></p><h1 style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 20pt; font-family: &quot;Arial&quot;; text-align: center; font-weight: bold;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">INTRODUÇÃO AO MODELO A DE METABOLISMO INFORMACIONAL</span></h1><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; height: 11pt; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; height: 11pt; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: center;"><span style="margin-right: 0px; margin-left: 0px; width: 20.03px; height: 20px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image16.png" style="width: 20.03px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; height: 11pt; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; height: 11pt; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: right;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:10pt;font-family:&quot;Newsreader&quot;;font-style:normal">POR HORUS C.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">O modelo A (Augusta) de metabolismo informacional é a peça-chave para entender um dos mais discutidos ramos da </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“sociomática”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, ao qual sua criadora designou de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“sociônica”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. A partir de uma óptica paradoxal e dicotômica, tornou-se possível seccionar o fenômeno fundamental de qualquer sociedade (o </span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Socion</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) em dezesseis tipos de relações entre dezesseis tipos de personalidade, inteligência ou metabolismo. Este breve escrito deve bastar para fundamentar as principais perspectivas desse eixo teórico ou, como sua criadora tanto gostava de atribuir, nova </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“ciência social”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; height: 11pt; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal"></span></p><h2 style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 16pt; font-family: &quot;Arial&quot;; text-align: justify; font-weight: bold;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:13pt;font-family:&quot;Newsreader&quot;;font-style:italic">Aušra “Augusta” Augustinavičiūtė:</span></h2><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">É relativamente comum que, no desenvolvimento de ideias e teorias novas, seus reais pioneiros sejam excluídos ou reduzidos a mera criação do esboço aceito. Esses casos parecem recair ainda mais quando a mente detrás de um estudo não é um homem ou está plenamente submissa ao papel patriarcal da sociedade moderna. Esse terrível e injusto evento parece ser muito adequado ao caso de Aušra Augustinavičiūtė ou, como preferia ser chamada, </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Augusta”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Em 1921, o psiquiatra suíço C. G. Jung publicou oficialmente uma das suas maiores e mais revolucionárias obras, </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Tipos Psicológicos”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, introduzindo novas questões e público a antiga possibilidade de compreender a personalidade humana sob esquemas, representações intelectuais e, sobretudo, em vias analíticas e científicas. Muitas propostas revolucionárias vieram da contribuição do psiquiatra, incluindo o popular </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Teste do MBTI”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;(Myers-Briggs Type Indicator), ao qual simplificava as pesquisas de Jung de forma acessível à população geral, apesar da falta de conhecimento ou noção destes sob princípios médicos ou psicológicos.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Entre os inúmeros autores que se espelharam na pesquisa de Jung, a década de 80 iniciou-se com a ilustre publicação do que seria, a partir dali designado, a </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">‘Teoria Sociônica’</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">. O principal nome detrás do grupo de pesquisadores pioneiros nesse novo estudo era Augusta, uma economista, psicóloga e socióloga lituana que, observando as mobilizações vigentes e as contribuições científicas ao ramo do comportamento e da formação da sociedade, tentou aproximar toda a proposta de Jung a um problema central em sua vida e cultura: a diferente manifestação psicológica das pessoas, suas capacidades e vulnerabilidades, além da relação que estas tinham na criação de civilizações, sociedades e culturas.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">Augusta nasceu na Lituânia, não muito longe da cidade de Kaunas. Em 1956, formou-se na Faculdade de Economia da Universidade de Vilnius. Seu contato com Jung deu-se no período entre sua formação e a década que antecede o início de suas publicações, aproximadamente em 1970; sua visão mais cética, menos centrada na psicologia profunda que Jung e, consequentemente, Sigmund Freud almejavam explorar fez com que a psicóloga passasse a focar em fenômenos mais concretos, ou melhor, mais ligados ao fenômeno socioeconômico.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">A fama não vem facilmente, o mesmo ocorreu com Augusta; sua proposta era, decerto, revolucionária, mas era muito exigente para os poucos intelectuais vigentes. Muito provavelmente seu primeiro clube sobre sua teoria, fora os anos que passou a esboçá-la a sós ou com amigos íntimos (o caso com Nikolai Medvedev), tem data em seu encontro com Igor Weisband, profundo colaborador e comentador de sua obra. Em seu texto em homenagem a Augusta, meses após seu falecimento, o </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“socionista”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;narra como fora esse seu primeiro encontro com a pioneira do estudo:</span><sup style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); vertical-align: super;"><a href="#ftnt1" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[1]</a></sup></p><p style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 56.7pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:11pt;font-family:&quot;Newsreader&quot;;font-style:normal">“Um dia, encontrei minha amiga Natasha Morozova na rua.</span></p><p style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 56.7pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:11pt;font-family:&quot;Newsreader&quot;;font-style:normal">— Você se interessa por psicologia, não é? — disse ela. Eu já havia fundado meu próprio clube de psicologia na Casa dos Cientistas; era um ponto de encontro boêmio e pitoresco.</span></p><p style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 56.7pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:11pt;font-family:&quot;Newsreader&quot;;font-style:normal">— Aušra Augustinavičiūtė esteve aqui enquanto você estava fora e falou sobre a sociônica.</span></p><p style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 56.7pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:11pt;font-family:&quot;Newsreader&quot;;font-style:normal">— O que é isso?</span></p><p style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 56.7pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:11pt;font-family:&quot;Newsreader&quot;;font-style:normal">— É melhor você ouvir por si mesmo. A esposa de Oleg Bakhtiyarova organizou um seminário. Eles se reúnem às quintas-feiras.</span></p><p style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 56.7pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Comecei a frequentar o seminário. Sveta Bakhtiyarova não vinha regularmente e, por hábito como presidente da seção de psicologia e pelo meu fanatismo crescente (senão eu, quem?), logo assumi o controle. A partir do teste aplicado me diagnostiquei como um tipo Yesenin (</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image2.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image1.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">). Logo mais Augusta voltou a Kiev. Estávamos andando de trólebus juntos e comecei a expor algumas ideias para ela com entusiasmo; ela me interrompeu no ponto mais interessante, com seu jeito encantador e peremptório: ‘Você não é Yesenin (</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image2.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image1.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">), você é um Dom Quixote (</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image8.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image3.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">)’. Então foi a própria fundadora do movimento que me nomeou como Dom Quixote. E às vezes me pergunto o que teria acontecido se ela não o tivesse feito? Eu teria continuado trabalhando tranquilamente na Sociônica e criado minha própria escola. Eu teria nomeado aqueles de quem eu gostava como meus tipos complementares e mobilizadores. Eu teria defendido meu diagnóstico de forma ativa e com grande fervor polêmico, como é costume na Sociônica – sem me preocupar com provas, mas citando o óbvio. Eu apoiaria com prazer a opinião de que Yesenin é o meu próprio tipo, justo ele, o mais típico de todos os tipos. O leve sarcasmo aqui se deve a uma tentativa de me redimir por aqueles pe</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">cados da Sociônica, pela emergência ou desenvolvimento dos quais participei pessoalmente”.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">O charme de Augusta não estava na conquista sedutora, na promessa por futuros melhores ou no ceder bens e financiamento; seu temperamento inventivo e democrático era facilmente percebido e reconhecido por seus colegas e amigos, comentados e cristalizados nas homenagens que seguiram seu fim, como no caso do relato de G. A. Schulman:</span></p><p style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 56.7pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">“Augusta, defendia o direito de cada tipo metabólico-informacional ser ele </span><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">mesmo</span><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, enfatizou repetidamente — mesmo em conversas privadas — o papel excepcional que cada um dos dezesseis sociotipos têm no desenvolvimento da ciência e do progresso científico e tecnológico em geral. Certa vez, em resposta ao meu comentário de que os Dom Quixotes às vezes não ouvem ninguém além de si mesmos, ela respondeu de forma bastante incisiva: ‘</span><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; font-style: italic; color: rgb(0, 0, 0);">Quem Dom Quixote deveria ouvir senão a si mesmo?!’</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:11pt;font-family:&quot;Newsreader&quot;;font-style:normal">.</span></p><p style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 56.7pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Ela mesma escreveu: </span><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; font-style: italic; color: rgb(0, 0, 0);">‘Não existem tipos de inteligência mais ou menos valiosos. Todos são indispensáveis ​​na corrida de revezamento do progresso social. Mas um exame dos tipos de metabolismo informacional das pessoas mais notáveis ​​e famosas dos últimos séculos é intrigante. A proporção de pessoas de um único tipo — por exemplo, de Intuitivos-Lógicos Extratímicos — é muito alta. Muitas pessoas desse tipo trabalharam por muitos anos, sem serem reconhecidas por ninguém, por sua própria conta e risco, sem encontrar apoio de seus companheiros de tribo, o que é bastante raro com indivíduos de outros sociotipos, caso decidam seguir algum caminho’.</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:11pt;font-family:&quot;Newsreader&quot;;font-style:normal">”.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">As reuniões passaram de clubes fechados para ocupações maiores; grande parte das contribuições emergiram das discussões realizadas na Casa dos Professores Kyiv, localizada na União das Repúblicas Socialistas Soviéticas (URSS), atual Ucrânia. A formalização e a publicação de teses acadêmicas só tiveram início a partir do ano de 1995 na revista pessoal dos socionistas vigentes: </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Socionics, Mentology and Personality Psychology</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">. Um retrato fiel e subjetivo do lar de discussões, Casa dos Professores, foi fornecido na homenagem de A. V. Bukalov:</span></p><p style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 56.7pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:11pt;font-family:&quot;Newsreader&quot;;font-style:normal">“Em 1986, fui convidado para a Casa dos Professores de Kyiv, onde um pequeno grupo de pessoas interessadas em psicologia e na tipologia de Jung se reunia no âmbito do novo campo da Sociônica. Este era o nascente Clube de Sociônica, que, ao longo de dois ou três anos, matriculei-me na Escola de Sociônica de Kyiv. Lá, tive meu primeiro contato com os robôs fotocopiados de Aušra, que eram distribuídos gratuitamente entre todos os interessados: Aušra Augustinavičiūtė visitou Kyiv diversas vezes e ministrou palestras públicas no Instituto de Cibernética da Academia Ucraniana de Ciências. Ao contrário dos psicólogos ideológicos que receberam seu trabalho com hostilidade, os ciberneticistas e especialistas em ciência da informação e modelagem da inteligência receberam as novas ideias de Augusta sobre a estrutura informacional da psique humana com grande interesse e entusiasmo. Nos primeiros trabalhos de Augusta, fiquei impressionado com a clareza, a precisão e a lógica de seu pensamento. Tendo considerado anteriormente muitas das ideias de Freud e Jung, pude perceber rapidamente as conexões internas entre várias coisas que ou não haviam sido mencionadas ou haviam recebido pouca atenção. Augusta descreveu o modelo informacional da psique — modelo A — e as relações intertipológicas com incrível clareza e beleza. O gênio de Augusta deu origem à Sociônica, e ela emergiu no mundo como Palas Atena, surgindo em armadura e bradando um grito de guerra da cabeça de Zeus diante dos olhos atônitos dos deuses. A própria Augusta tinha um espírito guerreiro”.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">O primeiro texto, que inicia as teses de Augusta sobre a Sociônica, foi escrito e divulgado aos poucos até ser </span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">publicada</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;na revista </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Socionics, Mentology, and Personality Psychology</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;no ano de 1995. Este primeiro artigo introduziu sua teoria, ou melhor, sua metodologia que integrava a hipótese de C.G. Jung a grandes autores da época — especialmente no âmbito psicológico comportamental — incluindo Ivan Pavlov, E. Kretschmer, A. E. Lichko e A. </span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Kepinski</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. O resultado disso foi uma </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“tipologia informacional-comportamental”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, menos centrada na </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“alma”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;e mais direcionada à relação que dois ou mais indivíduos apresentam, explicitamente, na sociedade.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Durante o período de 1980 e 1981, Augusta publicou poucos e curtos textos sobre análises gerais, centradas na demografia e na economia, pouco direcionados a sua pesquisa. Contudo, em 1982, a psicóloga publicou sua primeira monografia (revisada), denominada de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Theory of Intertype Relations”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. Sua proposta, diferente do primeiro artigo, não era propor integração teórica, mas expor os dados que colheu e a metodologia que começaria a traçar; isso se comprova pois, além de expor ao público pela primeira vez o que pensava determinar certos tipos de relações entre diferentes tipos de pessoas, Augusta também passou a introduzir um fenômeno maior, ao qual só passaria a descrever em sua segunda monografia, denominada de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“The Socion”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;(1982). A soma dos textos produzidos pela psicóloga durante este ano foram essenciais para expor seu objetivo como pesquisa, o seu objeto de estudo e, sobretudo, embasar com a possibilidade hipotética de um fenômeno social superior, o denominado </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Socion”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, e suas diferentes partes encarnadas em diferentes </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“temperamentos”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“tipos”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, que narram como a proposta de um </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“metabolismo informacional”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;(Cf. A. </span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Kepinski</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">) poderia exemplificar a formação cultural e social.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; height: 11pt; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal"></span></p><h2 style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 16pt; font-family: &quot;Arial&quot;; text-align: justify; font-weight: bold;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:13pt;font-family:&quot;Newsreader&quot;;font-style:italic">Os elementos de reflexão:</span></h2><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">O principal mecanismo psicológico abordado por Augusta no viés sociônico são os elementos de reflexão. Esse processo se dá, mais ou menos, como aparelhos cerebrais de menor porte, capazes de traduzir a realidade objetiva em aspectos menores e cognoscíveis para a consciência humana. Um perfeito reflexo da perspectiva de Augusta na ciência foi traçado, anteriormente, por I. V. Pavlov e seus sistemas de sinais primário e secundário. Segundo o autor, este primeiro </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“é tudo que internalizamos e fundamentamos em impressões, sensações e ideias do ambiente natural e social circundante”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">; enquanto o último tem </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“as palavras como fundamento do sistema de sinais secundário da realidade, que é específico a nós (seres humanos) e serve-nos como sinalização sob nossa sinalização primária”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">. Em suma, a psique humana é constituída por dois sistemas:</span></p><ul style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0);"><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">um capaz de internalizar impressões, sensações e estímulos do ambiente;</span></li><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">e outro capaz de processar o primeiro tipo e verbalizá-lo.</span></li></ul><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">Os elementos de reflexão, como qualidades da psique humana diferenciada, narram ambos os sistemas, de forma que é capaz de servir tanto para a internalização quanto a verbalização, i.e., a aplicação e a replicação de informações e estímulos.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Quem cedeu grande parte das ideias sobre os elementos e seus nomes para Augusta? Definitivamente foi uma soma dos estudos de C. G. Jung e A. </span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Kepinski</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. Enquanto a teoria do metabolismo abrange grande parte dos modelos de psique, as peças estruturantes de um sujeito foram definidas por Jung e sua ilustre obra </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Tipos Psicológicos</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;(1921). Segundo Augusta, a proposta de um modelo quádruplo de elementos foram perfeitos, mas negava que apenas quatro tipos de aspectos poderiam ser expressos pela psique, mas sim oito (referente aos oito tipos psicológicos completos de Jung); dessa forma, um modelo mais ou menos geral de elementos poderia ser traçado, onde os primeiros dois elementos são </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“irracionais”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;(ou ciclotímicos) e os dois últimos, </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“racionais”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;(ou esquizotímicos):</span></p><ul style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0);"><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">(</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image12.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">) — Intuição;</span></li><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">(</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image13.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">) — Sensação;</span></li><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">(</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image7.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">) — Ética;</span></li><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">(</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image11.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">) — Lógica.</span></li></ul><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">Dos tipos psicológicos de Jung, os oito elementos poderiam ser traçados do seguinte modo:</span></p><ul style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0);"><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">(</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image8.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">) — Intuição Extratímica;</span></li><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">(</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image2.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">) — Intuição Introtímica;</span></li><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">(</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image6.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">) — Sensação Extratímica;</span></li><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">(</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image9.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">) — Sensação Introtímica;</span></li><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">(</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image1.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">) — Ética Extratímica;</span></li><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">(</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image5.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">) — Ética Introtímica;</span></li><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">(</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image4.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">) — Lógica Extratímica;</span></li><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">(</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image3.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">) — Lógica Introtímica.</span></li></ul><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Qual a principal diferença entre os elementos extratímicos e introtímicos? Em suma, seria qual dos aspectos de uma mesma natureza (macro-conceito ou elemento) eles decidem refletir: se são as sensações ou </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“campos psicológicos”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;entre corpos, ou aspectos inerentes a esses últimos. Talvez a melhor forma de analisar isso seja compreendê-los em objetos inanimados, como a relação do sol e da terra:</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: center;"><span style="margin-right: 0px; margin-left: 0px; width: 275px; height: 203.87px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image10.png" style="width: 275px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Aspectos extratímicos são inerentes aos corpos, portanto o sol e a terra possuem em sua essência elementos </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“corporais”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;que narram suas propriedades e processos como objetos. Os aspectos introtímicos, por sua vez, são campos entre corpos, produzidos por sua interação. Em um caso mais específico, a </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">ética extratímica</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;(</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image1.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) do sol — que narra seus processos químicos inerentes — afeta a </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">ética extratímica</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;(</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image1.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) da terra através do campo de interação entre ambos os astros, representada pela </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">ética introtímica</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;(</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image5.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">):</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: center;"><span style="margin-right: 0px; margin-left: 0px; width: 275px; height: 203.87px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image14.png" style="width: 275px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Durante seus escritos, Augusta fornece diferentes explicações para cada elemento de reflexão; contudo, optei em expor a definição mais recente, encontrada em </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Socionics: </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Psychotypes</span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">&nbsp;and Tests</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;(1996):</span></p><ul style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0);"><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Intuição Extratímica (</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image8.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) — </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">O conteúdo implícito</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. “A energia potencial de um objeto, seu conteúdo e estrutura implícita, suas capacidades internas. O </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">‘programa’</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;embutido no objeto. Quaisquer habilidades concretas de uma pessoa. O que Karl Marx chamou de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">‘força laboral’</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">, ou seja, o conjunto das capacidades físicas e mentais do indivíduo. Uma percepção da presença de habilidades e capacidades internas ocultas. Essa percepção permite determinar se um objeto ou fenômeno é permanente ou efêmero”.</span></li><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Intuição Introtímica (</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image2.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) — </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Tempo</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">. “Tanto o tempo objetivo quanto o tempo subjetivo de um objeto. A duração do funcionamento ou existência do objeto, que é determinada por sua energia potencial e pelo gasto dessa energia por unidade de tempo. A situação externa do objeto em relação a outros objetos, ou seja, sua posição no tempo. Intervalos de tempo entre eventos, a duração de eventos específicos, a sequência de eventos e processos, seu ritmo no tempo, rapidez e lentidão. Tudo isso se aplica tanto a processos externos quanto internos. Uma percepção da atualidade, da urgência ou da falta dela, etc. Uma percepção de onde os eventos atuais estão posicionados no tempo em relação a outros eventos”.</span></li><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Sensação Extratímica (</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image6.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) — </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Forma de um objeto</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">. “A energia cinética do objeto, sua prontidão para gastar energia. Suas qualidades externas – cor, contorno, lisura ou rugosidade da superfície. Mobilização explícita. A vontade de uma pessoa, sua capacidade e prontidão para usá-la em si mesma e nos outros. A percepção de se o objeto está pronto para exercer sua vontade, para demonstrar sua força, se o objeto é estético”.</span></li><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Sensação Introtímica (</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image9.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) — </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Estado</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. “A situação interna do objeto em relação a outros objetos, a maneira como outros objetos afetam o estado do objeto e se refletem nesse estado. Poderíamos chamar isso de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">‘reverberação’</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;do espaço dentro do objeto. O estado é condicionado por processos tanto externos quanto internos. Uma sensação de prazer, satisfação ou insatisfação física e estética”.</span></li><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Ética Extratímica (</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image1.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) — </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Dinâmica implícita</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">. “Processos internos que permanecem ocultos à vista, muitas vezes revelando-se através de sons que emanam do interior do objeto ou pela alteração da sua aparência (por exemplo, vermelhidão no rosto). Para as pessoas, isso abrange desde experiências emocionais até a digestão. Estados emocionais, humores, excitação, depressão. Uma percepção sobre se os impulsos internos são éticos e se é possível mudar algo que está acontecendo dentro de si ou em outro objeto”.</span></li><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Ética Introtímica (</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image5.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) — </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Força atrativa dos objetos</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">. “Isso pode ser chamado de ''distância subjetiva'' entre objetos. Quando se trata de pessoas, um exemplo disso é o amor e o ódio. A pessoa amada está perto mesmo a uma grande distância, e a pessoa odiada está longe mesmo estando próxima. Isso inclui a percepção da ética nos relacionamentos, a bondade ou as más qualidades de uma pessoa, o desejo ou a relutância, etc”.</span></li><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Lógica Extratímica (</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image4.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) — </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Dinâmica explícita</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">. “Evento, fato, ação, mudança de posição no espaço. Manifestação externa do processo, a forma que ele assume. O movimento do objeto no espaço e todas as outras formas de movimento externo de objetos. A percepção da lógica de uma ação e se algo que está acontecendo pode ser resistido”.</span></li><li style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 32.2pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Lógica Introtímica (</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image3.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) — </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">Espaço</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">. “A distância entre objetos, posição no espaço ou entre outros objetos, hierarquia. Um sistema como um agregado de distâncias que foram estabelecidas intencionalmente ou acidentalmente. Um sistema de relações objetivas e regidas por leis na natureza e na sociedade”.</span></li></ul><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Dicotomias sempre separam um todo em duas partes de quantidades iguais, nos elementos isso já aconteceu com os traços extratímicos-introtímicos, o mesmo pode ser visto em aspectos explícitos-implícitos, onde </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">a intuição</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;e </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">a ética</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;revelam-se como propriedades implícitas de corpos e relações, enquanto </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">a sensação</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;e </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">a lógica</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;são aspectos explícitos: aplicando em um outro mecanismo inanimado, como uma máquina de quatro tempos, a natureza desses elementos podem ser melhor descritos:</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: center;"><span style="margin-right: 0px; margin-left: 0px; width: 150.6px; height: 146.81px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image15.png" style="width: 150.6px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">A estrutura implícita de um corpo (I. </span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image8.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">), i.e., sua energia potencial, é transformada em energia cinética (III. </span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image6.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) através da combustão ou compressão (II. </span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image1.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) e expressa como trabalho (IV. </span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image4.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">). O processo estrutural e de transformação são, sempre, implícitos, ocultos ao olho nú, mas podendo ser inerente a um corpo (como no sistema acima) quanto em relações; por outro lado, o processo formal e de movimento de um corpo sempre são explícitos, visíveis, incluindo suas relações e campos psicológicos, que também são imediatos na experiência.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Por fim, outra forma de narrar esses mecanismos é através da dicotomia estático-dinâmico, determinado quais aspectos se revelam como processos ou em propriedades amostrais. Elementos estáticos percebem a realidade como algo parado e amostral, direcionando atenção a propriedades explícitas (</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image6.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) e implícitas (</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image8.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">), além de tentar abordar relações objetivas (</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image3.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) e subjetivas (</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image5.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">). Elementos dinâmicos, por sua vez, percebem a realidade como algo cinético e móvel, direcionando atenção a processos explícitos (</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image4.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) e implícitos (</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image1.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">), além de colisões físicas (</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image9.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">) e temporais (</span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image2.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">).</span></p><h2 style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 16pt; font-family: &quot;Arial&quot;; text-align: justify; font-weight: bold;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:13pt;font-family:&quot;Newsreader&quot;;font-style:italic">Modelo J — uma introdução aos tipos de metabolismo:</span></h2><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">O contato com o mundo de Jung foi o que providenciou a Augusta um modelo relativamente </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“básico”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;para compreender as pessoas: esse que passou a ser denominado de modelo J. O fato de que esse modelo é incapaz de atender as necessidades de ambos os estudos — i.e., tanto a proposta original de Jung quanto a nova ciência de Augusta — foi o que o tornou como mero intermediário: uma pista disso está em uma das monografias iniciais publicadas pela autora, designada de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“Commentary on Jung’s Typology &amp; an Introduction to Information Metabolism”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;(1982), onde ela mesma admite a complexidade de estudar Jung diretamente e explicita o seu método de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“traçar paralelos compreensíveis”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">. Augusta havia gostado da proposta de Jung por não buscar </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“patologizar”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;ninguém através de sua tipologia, mas sim criar uma ponte entre o desconhecido mecanismo subjacente da personalidade saudável e do conhecimento teórico:</span></p><p style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 56.7pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">“A tipologia de Jung é uma tipologia de </span><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; font-style: italic; color: rgb(0, 0, 0);">pessoas saudáveis</span><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;que, assim, permite entender a psique de uma pessoa doente, e não o contrário, como geralmente acontece. Mas na minha visão, ela </span><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; font-style: italic; color: rgb(0, 0, 0);">não</span><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;está completa.</span><sup style="font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0); font-size: smaller; vertical-align: super;"><a href="#ftnt2" style="text-decoration: underline; color: rgb(0, 0, 238);" target="_blank" rel="noopener noreferrer">[2]</a></sup><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;Jung forneceu apenas um mapa pertinente dos tipos humanos, que exigia conclusão e completação. Muitas reflexões e ponderações do autor desta tipologia são apenas hipóteses de trabalho, palpites ao tentar </span><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; font-style: italic; color: rgb(0, 0, 0);">projetar</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:11pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;um modelo da psique humana”.</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">Para ela, o modelo J (Jung) poderia centrar-se no debate de quatro elementos (que Jung denominou de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“tipos funcionais”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">: intuição, ética [sentimento], sensação e lógica [pensamento]) e em suas variações extratímicas e introtímicas (v. abaixo): desta forma, um modelo com oito elementos poderia resultar (seguindo regras) de dezesseis diferentes combinações com quatro elementos. O elemento que desempenha o papel principal na psique de um indivíduo fora chamado de </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“líder”</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;ou </span><span style="font-size: 12pt; font-family: &quot;Newsreader&quot;; font-style: italic; font-weight: 400; color: rgb(0, 0, 0);">“função líder”</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">&nbsp;sendo, no modelo J, uma exclusividade em atitudes:</span></p><p style="color: rgb(0, 0, 0); font-size: 11pt; margin-right: 56.7pt; margin-left: 0px; font-family: &quot;Arial&quot;; text-align: justify;"><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">“Em um </span><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; font-style: italic; color: rgb(0, 0, 0);">modelo J extratímico</span><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">, a </span><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; font-style: italic; color: rgb(0, 0, 0);">função líder</span><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;é extratímica, enquanto as outras três são introtímicas. Em um </span><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; font-style: italic; color: rgb(0, 0, 0);">modelo introtímico</span><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:11pt;font-family:&quot;Newsreader&quot;;font-style:normal">, o oposto é verdadeiro”. </span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: justify;"><span style="color:#000000;font-weight:400;text-decoration:none;vertical-align:baseline;font-size:12pt;font-family:&quot;Newsreader&quot;;font-style:normal">Dessa forma, poderia-se narrar os dezesseis tipos de intelecto do seguinte modo (as quatro primeiras linhas referem-se a tipos irracionais, enquanto as quatro últimas, aos racionais):</span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: center;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">a) </span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image8.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image3.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image5.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image9.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">b) </span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image2.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image4.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image1.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image6.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: center;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">c) </span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image8.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image5.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image3.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image9.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;d) </span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image2.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image1.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image4.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image6.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: center;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">e) </span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image6.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image3.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image5.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image2.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;f) </span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image9.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image4.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image1.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image8.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: center;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">g) </span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image6.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image5.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image3.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image2.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;h) </span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image9.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image1.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image4.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image8.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span></p><p style="margin-right: 0px; margin-left: 0px; color: rgb(0, 0, 0); font-size: 11pt; font-family: &quot;Arial&quot;; text-align: center;"><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">i) </span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image4.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image9.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image2.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt="Imagem do texto" src="./source-images/socionics/image5.png" style="width: 10px; margin-left: 0px; color: rgb(0, 0, 0); max-width: 100%;" title="" loading="lazy"></span><span style="font-size: 12pt; font-weight: 400; font-family: &quot;Newsreader&quot;; color: rgb(0, 0, 0);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;j) </span><span style="margin-right: 0px; margin-left: 0px; width: 10px; height: 10px; color: rgb(0, 0, 0);"><img alt=